import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> answer = new ArrayList<>();
        backtrack(candidates, target, 0, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(int[] candidates, int remain, int start,
                           List<Integer> path, List<List<Integer>> answer) {
        if (remain == 0) {
            answer.add(new ArrayList<>(path));
            return;
        }
        for (int i = start; i < candidates.length; i++) {
            if (candidates[i] > remain) {
                break;
            }
            path.add(candidates[i]);
            backtrack(candidates, remain - candidates[i], i, path, answer);
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> answer = new ArrayList<>();
        dfs(candidates, 0, target, new ArrayList<>(), answer);
        return answer;
    }

    private void dfs(int[] candidates, int index, int remain,
                     List<Integer> path, List<List<Integer>> answer) {
        if (remain == 0) {
            answer.add(new ArrayList<>(path));
            return;
        }
        if (index == candidates.length || candidates[index] > remain) {
            return;
        }

        path.add(candidates[index]);
        dfs(candidates, index, remain - candidates[index], path, answer);
        path.remove(path.size() - 1);

        dfs(candidates, index + 1, remain, path, answer);
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<List<Integer>>> dp = new ArrayList<>();
        for (int sum = 0; sum <= target; sum++) {
            dp.add(new ArrayList<>());
        }
        dp.get(0).add(new ArrayList<>());

        for (int candidate : candidates) {
            for (int sum = candidate; sum <= target; sum++) {
                for (List<Integer> previous : dp.get(sum - candidate)) {
                    if (!previous.isEmpty() && previous.get(previous.size() - 1) > candidate) {
                        continue;
                    }
                    List<Integer> next = new ArrayList<>(previous);
                    next.add(candidate);
                    dp.get(sum).add(next);
                }
            }
        }
        return dp.get(target);
    }
}

import java.util.*;

class Solution {
    private static class State {
        int start;
        int remain;
        List<Integer> path;

        State(int start, int remain, List<Integer> path) {
            this.start = start;
            this.remain = remain;
            this.path = path;
        }
    }

    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> answer = new ArrayList<>();
        Queue<State> queue = new ArrayDeque<>();
        queue.offer(new State(0, target, new ArrayList<>()));

        while (!queue.isEmpty()) {
            State state = queue.poll();
            if (state.remain == 0) {
                answer.add(state.path);
                continue;
            }
            for (int i = state.start; i < candidates.length; i++) {
                if (candidates[i] > state.remain) {
                    break;
                }
                List<Integer> nextPath = new ArrayList<>(state.path);
                nextPath.add(candidates[i]);
                queue.offer(new State(i, state.remain - candidates[i], nextPath));
            }
        }
        return answer;
    }
}
